'use client'

import { useState } from 'react'

// Sample venue data
const sampleVenues = [
  {
    id: 1,
    name: 'The Basement',
    type: 'Cafe',
    location: 'Downtown',
    lat: 19.0760,
    lng: 72.8777,
    capacity: 100,
    image: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=400&h=300&fit=crop',
    amenities: ['food', 'drinks', 'stage'],
  },
  {
    id: 2,
    name: 'Blue Note Cafe',
    type: 'Cafe',
    location: 'Midtown',
    lat: 19.0800,
    lng: 72.8800,
    capacity: 80,
    image: 'https://images.unsplash.com/photo-1465101046530-73398c7f28ca?w=400&h=300&fit=crop',
    amenities: ['food', 'drinks', 'sound_system'],
  },
  {
    id: 3,
    name: 'Warehouse Club',
    type: 'Club',
    location: 'Industrial Zone',
    lat: 19.0700,
    lng: 72.8700,
    capacity: 300,
    image: 'https://images.unsplash.com/photo-1464983953574-0892a716854b?w=400&h=300&fit=crop',
    amenities: ['drinks', 'stage', 'lighting'],
  },
  {
    id: 4,
    name: 'Coffee House',
    type: 'Cafe',
    location: 'University District',
    lat: 19.0850,
    lng: 72.8900,
    capacity: 60,
    image: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=400&h=300&fit=crop',
    amenities: ['food', 'wifi'],
  },
]

export default function VenuesPage() {
  const [search, setSearch] = useState('')
  const [type, setType] = useState('all')

  const types = ['all', ...Array.from(new Set(sampleVenues.map(v => v.type)))]

  const filteredVenues = sampleVenues.filter(venue => {
    const matchesType = type === 'all' || venue.type === type
    const matchesSearch = venue.name.toLowerCase().includes(search.toLowerCase()) ||
      venue.location.toLowerCase().includes(search.toLowerCase())
    return matchesType && matchesSearch
  })

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors duration-300">
      <div className="w-full py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center">
            <h1 className="text-4xl font-extrabold mb-2">Discover Venues</h1>
            <p className="mt-3 max-w-md mx-auto text-base sm:text-lg md:mt-5 md:text-xl md:max-w-3xl">
              Explore local venues, see amenities, and find your next gig spot.
            </p>
          </div>
        </div>
      </div>
      {/* Filters */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <input
              type="text"
              placeholder="Search venues or locations..."
              className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-foreground focus:border-foreground bg-background text-foreground"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="sm:w-48">
            <select
              className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-foreground focus:border-foreground bg-background text-foreground"
              value={type}
              onChange={e => setType(e.target.value)}
            >
              {types.map(t => (
                <option key={t} value={t}>{t === 'all' ? 'All Types' : t}</option>
              ))}
            </select>
          </div>
        </div>
      </div>
      {/* Venues Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-12">
        {filteredVenues.length === 0 ? (
          <div className="text-center py-12">
            <h3 className="text-lg font-medium">No venues found</h3>
            <p className="mt-2 text-gray-500">Try adjusting your search or filters</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredVenues.map(venue => (
              <div key={venue.id} className="bg-background rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow border border-gray-200 dark:border-gray-800">
                <img
                  src={venue.image}
                  alt={venue.name}
                  className="w-full h-48 object-cover"
                />
                <div className="p-6">
                  <div className="flex items-center justify-between mb-2">
                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-background text-foreground border border-gray-200 dark:border-gray-800">
                      {venue.type}
                    </span>
                    <span className="text-sm text-gray-500">{venue.location}</span>
                  </div>
                  <h3 className="text-lg font-semibold mb-1">{venue.name}</h3>
                  <p className="text-sm text-gray-600 mb-2">Capacity: {venue.capacity}</p>
                  <div className="flex flex-wrap gap-2 mb-2">
                    {venue.amenities.map(a => (
                      <span key={a} className="inline-block bg-background text-foreground border border-gray-200 dark:border-gray-800 text-xs px-2 py-0.5 rounded-full">
                        {a}
                      </span>
                    ))}
                  </div>
                  <button className="bg-foreground text-background py-1 px-4 rounded-md hover:opacity-90 transition-colors text-sm">View Details</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
} 